package cn.zhuatech.ehs.controller; import cn.zhuatech.ehs.common.ApiResponse; import cn.zhuatech.ehs.dto.EhsDto.*; import cn.zhuatech.ehs.service.EhsService; import jakarta.validation.Valid; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/shopfloor") @PreAuthorize("hasAnyRole('SAFETY_OFFICER','ADMIN')") public class SafetyOfficerController {private final EhsService service;public SafetyOfficerController(EhsService service){this.service=service;}@GetMapping("/dashboard") public ApiResponse<Dashboard> dashboard(){return ApiResponse.ok(service.shopfloorDashboard());}@PostMapping("/work-orders/{id}/reports") public ApiResponse<ReportResult> report(@PathVariable Long id,@Valid @RequestBody ReportRequest request){return ApiResponse.ok("反馈提交成功",service.report(id,request));}}
